package com.findit.servlet;
import com.findit.dao.ItemDAO;import javax.servlet.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.*;import java.sql.SQLException;
@WebServlet("/admin") public class AdminServlet extends HttpServlet {protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{HttpSession s=q.getSession(false);if(s==null||s.getAttribute("userId")==null){p.sendRedirect(q.getContextPath()+"/login");return;}if(!"ADMIN".equals(s.getAttribute("role"))){p.sendError(403,"Administrator access required.");return;}try{ItemDAO d=new ItemDAO();q.setAttribute("usersCount",d.count("users"));q.setAttribute("itemsCount",d.count("items"));q.setAttribute("claimsCount",d.count("claims"));q.setAttribute("claims",d.claims());q.setAttribute("items",d.list(null,null,0,false));q.getRequestDispatcher("/WEB-INF/views/admin.jsp").forward(q,p);}catch(SQLException e){throw new ServletException(e);}}}
